			//Sowmya - 10560
			function onChangeHandler() {
                var srSelectSelector = "input[aria-labelledby^='Notification_Method_Label_'], input[aria-labelledby^='Type_Label_'], input[aria-labelledby^='Area_Label_']";
                ensureSrSelectPlaceholderStyle();
                $(srSelectSelector).each(function () {
                    updateSrSelectPlaceholderState(this);
                });
            }
            function ensureSrSelectPlaceholderStyle() {
                if ($("#vha-sr-select-placeholder-style").length) {
                    return;
                }
                $("head").append('<style id="vha-sr-select-placeholder-style">.vha-sr-select-wrap{position:relative;}.vha-sr-select-wrap::before{content:"Select";position:absolute;left:8px;top:0;font-size:16px;bottom:10px;display:flex;align-items:center;color:#a3a3ad;pointer-events:none;line-height:20px;}.vha-sr-select-wrap:focus-within::before,.vha-sr-select-wrap.hasValue::before{content:"";}</style>');
            }
            function updateSrSelectPlaceholderState(field) {
                var $field = $(field);
                var fieldVal = ($field.val() || "").replace(/\u00a0/g, "").trim();
                var $wrapper = $field.closest(".siebui-value, .mceField, .mceGridField").first();
                if (!$wrapper.length) {
                    return;
                }
                $field.attr("placeholder", "Select");
                $wrapper.addClass("vha-sr-select-wrap");
                $wrapper.toggleClass("hasValue", fieldVal !== "");
            }
