    function bannerFocus(type) {
				let banner = "";
				if(type === "stockcheck"){//Marvin : CM-10406
					banner = document.querySelector('.vha-scj-mobiletab:not(.displaynone) .carosuel-main') || document.querySelector('.vha-scj-tablets-tab:not(.displaynone) .carosuel-main') || document.querySelector('.vha-scj-accessory-tab:not(.displaynone) .carosuel-main') || document.querySelector('.vha-scj-wearbles-tab:not(.displaynone) .carosuel-main')||document.querySelector('.vha-scj-accessory-tab:not(.displaynone) .carosuel-main')||document.querySelector('.vha-scj-accessoryfx-tab:not(.displaynone) .carosuel-main')||document.querySelector('.vha-scj-modem-tab:not(.displaynone) .carosuel-main');
				}else{
					banner = document.querySelector('.current-plan-warning-box') || document.querySelector('.header-validations-warning-box:not(.displaynone)'); //Sowmya - 10519
				}
                if (banner) {  
                    let parent = banner.parentElement;
                    while (parent) {
                        const style = window.getComputedStyle(parent);
                        const overflowY = style.overflowY;
                        if (overflowY === 'auto' || overflowY === 'scroll') {
                            break;
                        }
                        parent = parent.parentElement;
                    }    
                    if (parent) {
                        parent.scrollTo({
                            top: banner.offsetTop - 20,   
                            behavior: 'smooth'
                        });
                    } else {
                        banner.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                
                    banner.setAttribute('tabindex', '-1');
                    banner.focus();
                }				
            }


