               // });
$(".vha-scj-check-str-popup-input").on("input", function () {
                        var $input = $(this);
                     
                        if ($input.data("ui-autocomplete"))
                            return;
                    
                        var $popupContent = $input.closest(".vha-scj-check-str-popup-content");
                    
                        $input.autocomplete({
                            minLength: 4,
                            classes: {
                                "ui-autocomplete": "vha-checkstrStock-autocomplete-menu" 
                            },
                            appendTo: $popupContent.length ? $popupContent : "body",   
                            position: {
                                my: "left top",
                                at: "left bottom",
                                of: $input
                            },
                            source: function (request, response) {
                                try {
                                    var inputVal = request.term;
                                    var isNumeric = /^\d+$/.test(inputVal);
                    
                                    var ser = SiebelApp.S_App.GetService("Workflow Process Manager");
                                    var Inputs = SiebelApp.S_App.NewPropertySet();
                                    Inputs.SetProperty("ProcessName", "VHA SSJ PostCode Check Process");
                    
                                    if (isNumeric) {
                                        Inputs.SetProperty("PostCode", inputVal);
                                        Inputs.SetProperty("SubUrb", "");
                                    } else {
                                        Inputs.SetProperty("PostCode", "");
                                        Inputs.SetProperty("SubUrb", inputVal);
                                    }
                    
                                    var Output = ser.InvokeMethod("RunProcess", Inputs);
                                    var data = Output.GetChildByType("ResultSet")
                                                    .childArray[0].childArray[0].childArray;
                    
                                    var suggestions = [];
                    
                                    data.forEach(function (item) {
                                        var props = item.propArray;
                                        var suburb   = props["Suburb"]   || "";
                                        var postcode = props["Postcode"] || "";
                                        var state    = props["State"]    || "";
                                        var longitude = props["Longitude"] || "";
                                        var latitude  = props["Latitude"]  || "";
                    
                                        var label = suburb + ", " + postcode + ", " + state;
                    
                                        suggestions.push({
                                            label: label,
                                            value: label,
                                            latitude: latitude,
                                            longitude: longitude,
                                            type: "Checkstorestock"
                                        });
                                    });
                    
                                    response(suggestions);
                                } catch (e) {
                                    //alert unbale to search
                                }
                            },
                            select: function (event, ui) {
                                console.log("Selected:", ui.item);
                                checkstocktable(ui.item.latitude, ui.item.longitude);
                            }
                        })
                        
                        .autocomplete("instance")._resizeMenu = function () {
                            var ul = this.menu.element;
                            ul.outerWidth(this.element.outerWidth());
                        };
                    });
