                function hideMbbCounterIfNeeded() { //dhana_CM-7313
                    const hasPlan = currentRLI[0].PlanItem && Object.keys(currentRLI[0].PlanItem).length > 0;
                    const hasDevice = currentRLI[0].DeviceItem && currentRLI[0].DeviceItem.length > 0;
                    const hasTablet = currentRLI[0].TabletItem && currentRLI[0].TabletItem.length > 0;

                    if (hasPlan && (hasDevice || hasTablet)) {
                        $('.mbPlanCounter').addClass('displaynone').find('.planCount').val(0);

                        // Remove all nodes except currentRLI[0]
                        if (currentRLI.length > 1) {
                            currentRLI.splice(1); // Deletes everything from index 1 onwards
                            selectedPlans.splice(1);
                        }
                    }
                }
