                function determineJourneyType() {
                    let startDate = filteredExistingServices.ListOfRatePlan.RatePlan["Start Date"];
                    let endDate = filteredExistingServices.ListOfRatePlan.RatePlan["End Date"];
                    // Determine upgrade or rpc service type
                    // 1. Plan and Mobile
                    if ((Object.keys(currentRLI[0].PlanItem).length > 0) && (currentRLI[0].DeviceItem.length > 0 || currentRLI[0].TabletItem.length > 0) || Object.keys(currentRLI[0].FixedPlanItem).length > 0 && currentRLI[0].FixedmodemItem.length > 0) {
                        currentRLI[0].SrvType = "Upgrade Service";
                        ssjUpgradeType = "Upgrade to New plan";
                        upgradeEligibilityCheck();
                    }
                    // 2. Plan
                    else if ((Object.keys(currentRLI[0].PlanItem).length > 0) && (currentRLI[0].DeviceItem == 0 && currentRLI[0].TabletItem == 0)) {
                        if ((currentRLI[0].PlanItem.PaymentTerm != "Month to month") && (startDate != undefined) && (endDate != undefined)) { //CM-6719 -Dhana
                            evaluatePlanForUpgradeOrRpc();
                        } else {
                            if ((currentRLI[0].PlanItem.PlanJourneyType === "RPC") || (currentRLI[0].PlanItem.PlanJourneyType === "UniqueRPC")) {
                                currentRLI[0].SrvType = "Modify Service";
                                // ssjUpgradeType = "Upgrade to New plan";  //check for RPC is required or not
                                updateExistingService();
                            } else {
                                currentRLI[0].SrvType = "Upgrade Service";
                                ssjUpgradeType = "Upgrade to New plan";
                                upgradeEligibilityCheck();
                            }
                        }
                    }
                    // 3. Mobile
                    else if ((Object.keys(currentRLI[0].PlanItem).length === 0) && (currentRLI[0].DeviceItem.length > 0 || currentRLI[0].TabletItem.length > 0)) {
                        currentRLI[0].SrvType = "Upgrade Service";
                        ssjUpgradeType = "Upgrade RRP on Installment";
                        upgradeEligibilityCheck();
                    }
                    // Fixed plan
                    else if (Object.keys(currentRLI[0].FixedPlanItem).length > 0 && currentRLI[0].FixedmodemItem.length === 0){//Fixed- RPC Jeeten: 22-01-25
                        currentRLI[0].SrvType = "Modify Service";
                        // ssjUpgradeType = "Upgrade to New plan";  //check for RPC is required or not
                        updateExistingService();
                    }
                    //Fixed Modem 
                    else if ( (Object.keys(currentRLI[0].PlanItem).length === 0)&& (currentRLI[0].FixedmodemItem.length > 0)) { //Dhana
                        currentRLI[0].SrvType = "Upgrade Service";
                    }
                }

                function upgradeEligibiltyBsCall(exstServ) {
                    var BS = SiebelApp.S_App.GetService("Workflow Process Manager");
                    var Inputs = SiebelApp.S_App.NewPropertySet();
                    Inputs.SetProperty("ProcessName", "VHA SSJ Check Upgrade Eligibility WF");
                    Inputs.SetProperty("Object Id", exstServ.AssetId);
                    var Output = BS.InvokeMethod("RunProcess", Inputs);
                    if (Output) {
                        var eligibilityResponse = Output.GetChildByType("ResultSet").propArray;
                    }
                    return eligibilityResponse;
                }

                function upgradeEligibilityCheck() {
                    let eligibilityResponse;

                    if (!ssjUpgradeType) {
                        return false;
                    }

                    var eid = $('#vha-edit-lnk').attr('data-id');
                    let exstServ = scJson.QuoteHeader.ExistingServices[0].filter(obj => obj.MSISDN === eid)[0];

                    // Call Siebel WF
                    if (ssjUpgradeType === "Upgrade to New plan" || ssjUpgradeType === "Upgrade RRP on Installment") {
                        eligibilityResponse = upgradeEligibiltyBsCall(exstServ);

                    }

                    // Apply logic
                    if (eligibilityResponse) {
                        var overrideResp = eligibilityResponse.EnableTenureOverride;
                        // Y/N
                        var eligUpgrade = eligibilityResponse.DisplayEligForUpgrade;
                        // Y/N
                        var eligOutright = eligibilityResponse.DisplayEligForOutright;
                        // Y/N

                        if (overrideResp === "Y") {
                            if (ssjUpgradeType === "Upgrade RRP on Installment") {
                                if (eligOutright === "N") {
                                    upgradeEligibilityshowPopupHardStop();
                                    return false;
                                } else if (eligOutright === "C") {
                                    upgradeEligibilityshowPopupOverride();
                                    return false;
                                } else {
                                    updateExistingService();
                                }

                            } else if (ssjUpgradeType === "Upgrade to New plan") {
                                if (eligUpgrade === "N") {
                                    upgradeEligibilityshowPopupHardStop();
                                    return false;
                                } else if (eligUpgrade === "C") {
                                    upgradeEligibilityshowPopupOverride();
                                    return false;
                                } else {
                                    updateExistingService();
                                }
                            }
                        }
                        if (overrideResp === "N") {
                            if (ssjUpgradeType === "Upgrade RRP on Installment") {
                                if (eligOutright === "N") {
                                    upgradeEligibilityshowPopupHardStop();
                                    return false;
                                } else {
                                    updateExistingService();
                                }
                            } else if (ssjUpgradeType === "Upgrade to New plan") {
                                if (eligUpgrade === "N") {
                                    upgradeEligibilityshowPopupHardStop();
                                    return false;
                                } else {
                                    updateExistingService();
                                }
                            }
                        }
                    }
                }

