                // Render Existing Services UI: Jeeten
                function fetchExistingServices(billAccId) {
                    const CustDetails = VHAAppUtilities.ExistingCustdeatilsWF(billAccId); //"230004556"
                    const resultSetBS = CustDetails?.GetChildByType("ResultSet");
					//Marvin: Added for CM-9247 CR.
					scJson.QuoteHeader.NotBusinessAccnt = resultSetBS?.propArray["AllowAccesoryWearable"];
                    if (resumeQuote === "Y") {
                        fetch_cust_detail(resultSetBS);
                        if (scJson.QuoteHeader.ExistingServices?.[0]?.length > 0 && scJson.QuoteHeader.ExistingServices?.[0]?.[0] !== undefined) {
								renderExistingService();
							};
                    } else {
                        const finalOutput = resultSetBS?.childArray?.[0]?.childArray?.[0]?.childArray?.[0]?.childArray?.[0];
                        let Jsonresult = VHAAppUtilities.psToJSON(finalOutput);
                        //let Jsonresult = VHAAppUtilities.propertySetToJson(finalOutput);
                        SiebelApp.S_App.ext = Jsonresult;
                        if (Jsonresult) {
                            //scJson.QuoteHeader.ExistingServices.push(Jsonresult.MSISDNDetails);
                            if (!Array.isArray(Jsonresult.MSISDNDetails)) {
                                scJson.QuoteHeader.ExistingServices.push([Jsonresult.MSISDNDetails]);
                            } else {
                                scJson.QuoteHeader.ExistingServices.push(Jsonresult.MSISDNDetails);
                            }
                            fetch_cust_detail(resultSetBS);
                            if (scJson.QuoteHeader.ExistingServices?.[0]?.length > 0 && scJson.QuoteHeader.ExistingServices?.[0]?.[0] !== undefined) {
								renderExistingService();
							};
                        }
                    }

                };

                //Jeeten: 8-feb: fetch billing account Details
                function fetchBillingAccDetails(billAccId){
                    var ai = {};
                    ai.async = true;
                    ai.selfbusy = true;
                    ai.scope = this;
                    ai.mask = true;
                    ai.opdecode = true;
                    ai.errcb = function () {
                        console.log("Async - fetchBillingAccDetails: failed");
                    };
                    ai.cb = function () {
                        console.log("Async - fetchBillingAccDetails: Success");
                        //console.log(psOutputs1.GetChildByType("ResultSet").GetChild(0));
                        psOutputs = arguments[2].childArray[0];
                        var sDiv = $('.vha-billing-change-tabs-cont');
                        let astintId="";
                        var sTxt = "There is an order in progress on this account. Actions may be limited.";
                        let eMsg="";
                        let msg = "";
                        psOutputs = (psOutputs != null && psOutputs.GetChildCount() > 0) ? psOutputs.GetChild(0) : null;
                        if(psOutputs){
                            $.map(psOutputs.childArray, function (ast) {
                                if (ast.propArray?.["OpenOrderExists"] === "Y") {
                                    astintId = ast.propArray["AstIntegId"];
                                    eMsg = ast.propArray["Error Message"];
                                    var $asset = $('[assetintid="' + ast.propArray["AstIntegId"] + '"]');
                                    var serviceAddr = $.trim($asset.attr("serviceaddr") || '');  // handles 
                                    if (serviceAddr){
                                        msg += '<li class="vha-warning-li">'+serviceAddr+' - Pending order submission</li>';										
                                    }else{
                                        msg += '<li class="vha-warning-li">'+$('[assetintid='+ast.propArray["AstIntegId"]+']').attr("data-id")+' - Pending order submission</li>';
                                    }							        
                                    $('#cart-container-'+$('[assetintid='+ast.propArray["AstIntegId"]+']').attr("data-id")+' .vha-pen-ord-sub').removeClass("displaynone");
                                    $('#cart-container-'+$('[assetintid='+ast.propArray["AstIntegId"]+']').attr("data-id")+' .item-edit-sec').addClass("displaynone");
                                    $('#cart-container-'+$('[assetintid='+ast.propArray["AstIntegId"]+']').attr("data-id")+' .item-cust-sec').addClass("pending-ord");
                                }
                            });
                            if(msg){
                                VHAAppUtilities.WarningBanner(sDiv, sTxt, "", msg);
                            }
                        }
                    };
                    
                    var bsRespCheck1 = SiebelApp.S_App.GetService("VF BS Process Manager");
                    var psInputs1 = SiebelApp.S_App.NewPropertySet();
                    var psOutputs1 = SiebelApp.S_App.NewPropertySet();
                    psInputs1.SetProperty("Service Name", "Workflow Process Manager");
                    psInputs1.SetProperty("Method Name", "RunProcess");
                    psInputs1.SetProperty("ProcessName", "VHA SSJ PLP Open Order Check WF");
                    psInputs1.SetProperty("BillAccId", SiebelApp.S_App.GetActiveView().GetAppletMap()['VHA SSJ Parent Order Form Applet'].GetBusComp().GetFieldValue("Billing Account Id"));
                    bsRespCheck1.InvokeMethod("Run Process", psInputs1, ai);
                }

