function capacityToGB(capStr) {
    if (!capStr) return 0;
    
    const str = String(capStr).trim().toUpperCase(); 
    const numMatch = str.match(/(\d+(\.\d+)?)/);
    if (!numMatch) return 0;

    const value = parseFloat(numMatch[1]);
   
    if (str.includes("TB")) {
        return value * 1024;
    }
    
    return value;
}

function sortStorageArray(storageArr) {
    if (!Array.isArray(storageArr)) return storageArr;

    return storageArr.slice().sort((a, b) => {
        return capacityToGB(a) - capacityToGB(b);
    });
}
