            function SortDevices(sortby) {

                const sortStrategies = {
                    mobile: {
                        priceHigh: (a, b) => b.rrpMax - a.rrpMax,
                        priceLow: (a, b) => a.rrpMin - b.rrpMin
                    },
                    tablet: {
                        priceHigh: (a, b) => b.rrpMax - a.rrpMax,
                        priceLow: (a, b) => a.rrpMin - b.rrpMin
                    },
                    accessory: {
                        priceHigh: (a, b) => b.propArray.RRP - a.propArray.RRP,
                        priceLow: (a, b) => a.propArray.RRP - b.propArray.RRP
                    },
                    Accessoryfx: { //Dhana_18feb
                        priceHigh: (a, b) => b.propArray.RRP - a.propArray.RRP,
                        priceLow: (a, b) => a.propArray.RRP - b.propArray.RRP
                    },
                    fixedModem: {
                        priceHigh: (a, b) => b.propArray.sRRPInGST - a.propArray.sRRPInGST,
                        priceLow: (a, b) => a.propArray.sRRPExGST - b.propArray.sRRPExGST
                    },
                    Wearble: {
                        priceHigh: (a, b) => b.rrpMax - a.rrpMax,
                        priceLow: (a, b) => a.rrpMin - b.rrpMin
                    }
                };

                const dataSources = {
                    mobile: filteredDevices,
                    tablet: filteredTablets,
                    accessory: filteredAccessories,
                    Accessoryfx: filteredAccessories, //Dhana_18feb
                    fixedModem: filteredmodems,
                    Wearble: filteredWearables
                };

                const renderFunctions = {
                    mobile: (data) => updateCarousel(ActiveTab, MobilecurrentIndex, sortby),
                    tablet: (data) => updateCarousel(ActiveTab, TabletcurrentIndex, sortby),
                    accessory: (data) => updateCarousel(ActiveTab, AccessorycurrentIndex),
                    Accessoryfx: (data) => updateCarousel(ActiveTab, AccessorycurrentIndex),
                    fixedModem: (data) => updateCarousel(ActiveTab, FixedmodemIndex, sortby),
                    Wearble: (data) => updateCarousel(ActiveTab, WearblecurrentIndex, sortby)
                };

                const sortFn = sortStrategies[ActiveTab]?.[sortby];
                const data = dataSources[ActiveTab];
                const render = renderFunctions[ActiveTab];

                if (sortFn && data && render) {
                    const sortedData = [...data].sort(sortFn);
                    if (ActiveTab === 'mobile') {
                        filteredDevices = sortedData;
                        MobilecurrentIndex = 0;
                    } else if (ActiveTab === 'tablet') {
                        filteredTablets = sortedData;
                        TabletcurrentIndex = 0;
                    } else if (ActiveTab === "accessory" || ActiveTab === "Accessoryfx") { //Dhana_17Feb
                        filteredAccessories = sortedData;
                        AccessorycurrentIndex = 0;
                    } else if (ActiveTab === 'Wearble') {
                        filteredWearables = sortedData;
                        WearblecurrentIndex = 0;
                    } else if (ActiveTab === 'fixedModem') {
                        filteredmodems = sortedData;
                        FixedmodemIndex = 0;
                    }
                    render(sortedData);
                } else {
                    console.log("Unknown sorting option or tab selected");
                }
            }
            //dhana changes for plans
