                // end

                //5910 ---------------
                function populatePropositionDropdown(objj, device) {
                    'use strict';
                
                    /* ================= DEFAULT PROPOSITIONS ================= */
                
                    var DEFAULT_MOBILE_PROP = 'Vodafone Postpaid Infinite MTM Aug 2025';
                    var DEFAULT_TABLET_PROP = 'Vodafone Postpaid Infinite Data MTM Plans Aug 2025';
                
                    var DEFAULT_PROP =
                        device === 'tablet' ? DEFAULT_TABLET_PROP :
                        device === 'mobile' ? DEFAULT_MOBILE_PROP :
                        null;
                
                    var key = device !== "fixedplans" ? "Proposition_Name" : "sPropoName";
                
                    /* ================= UNIQUE PROPOSITIONS ================= */
                
                    var uniqueProps = Array.from(new Set(
                        (objj || [])
                            .map(function (plan) {
                                var val = plan && plan.propArray && plan.propArray[key];
                                return (val && String(val).trim()) ? String(val) : null;
                            })
                            .filter(Boolean)
                    ));
                
                    var $container =
                        $('.availableplansheadingcontainer1[data-device="' + device + '"]');
                    if (!$container.length) return;
                
                    var $input =
                        $container.find('input[name="Selectbypropositionlist"].search-box');
                
                    /* ================= DESTROY OLD AUTOCOMPLETE ================= */
                
                    try {
                        if ($input.data('ui-autocomplete')) {
                            $input.autocomplete('destroy');
                        }
                    } catch (e) {}
                
                    /* ================= WILDCARD REGEX ================= */
                
                    function buildWildcardRegex(term) {
                        var escaped = term.replace(/[.+^${}()|[\]\\]/g, '\\$&');
                        escaped = escaped.replace(/\*/g, '.*').replace(/\?/g, '.');
                        return new RegExp(escaped, 'i');
                    }
                
                    /* ================= AUTOCOMPLETE SOURCE ================= */
                
                    var sourceFn = function (request, response) {
                        var term = String(request.term || '').trim();
                
                        // open dropdown only after typing
                        if (!term) {
                            response([]);
                            return;
                        }
                
                        var regex = buildWildcardRegex(term);
                
                        response(
                            uniqueProps.filter(function (v) {
                                return regex.test(v);
                            })
                        );
                    };
                
                    /* ================= AUTOCOMPLETE INIT ================= */
                
                    if ($.ui && $.ui.autocomplete) {
                        $input.autocomplete({
                            source: sourceFn,
                            minLength: 1,
                            autoFocus: true,
                            appendTo: 'body',
                
                            focus: function () {
                                return false;
                            },
                
                            select: function (event, ui) {
                                event.preventDefault();
                
                                var val = ui.item.value;
                                $input.val(val);
                
                                // ONLY place plans are updated
                                lastSelectedProposition = val;
                                filterByProposition(val, device);
                
                                addClearIcon();
                                $input.addClass('has-value'); //10454 hide search icon
                                $input.blur();
                            }
                        });
                    }
                
                    /* ================= CLEAR (X) ICON ================= */
                
                    function addClearIcon() {
                        if ($container.find('.clear-proposition').length) return;
                
                        var $clear = $('<span class="clear-proposition">&#10005;</span>');
                
                        $container.find('.d-flex').css('position', 'relative');
                
                        $clear.css({
                            position: 'absolute',
                            right: '10px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                            cursor: 'pointer',
                            fontSize: '16px',
                            color: '#666',
                            backgroundColor:'#fff'
                        });
                
                        $container.find('.d-flex').append($clear);
                    }
                
                    function removeClearIcon() {
                        $container.find('.clear-proposition').remove();
                    }
                
                    // clear icon click – clear input only
                    $container.off('click', '.clear-proposition')
                        .on('click', '.clear-proposition', function (e) {
                            e.stopPropagation();
                            $input.val('');
                            removeClearIcon();
                            $input.removeClass('has-value'); //10454 hide search icon
                            $input.blur();
                            // do NOT update plans
                        });
                
                    /* ================= INPUT WATCHER ================= */

                        $input.off('input.clearIcon').on('input.clearIcon', function () {
                            if ($(this).val()) {
                                addClearIcon();
                            } else {
                                removeClearIcon();
                            }
                        });

                         /* ================= INPUT FOCUS 10454================= */

                        $input.off('focus.hideSearchIcon')
                        .on('focus.hideSearchIcon', function () {
                            // 10454new hide search icon when input is focused
                            $(this).addClass('has-value');
                        }); 
                        
                        /* ================= INPUT BLUR 10454================= */

                        $input.off('blur.showSearchIcon')
                        .on('blur.showSearchIcon', function () {
                            if (!$(this).val()) {
                                // 10454 new --- show search icon only when input is NOT focused
                                $(this).removeClass('has-value');
                            }
                        });

                    /* ================= DEFAULT LOAD ================= */
                
                    if (DEFAULT_PROP) {
                        $input.val(DEFAULT_PROP);
                
                        lastSelectedProposition = DEFAULT_PROP;
                        filterByProposition(DEFAULT_PROP, device);
                
                        addClearIcon();
                        $input.addClass('has-value'); //10454 hide search icon
                    }
                }                
             
                
           function filterByProposition(proposition, device) {
                currPage = 0; //Juhi 10440
    let baseArray = [];

    if (device === "mobile") {
        baseArray = Array.isArray(jsonplans) ? jsonplans : [];
    } 
    else if (device === "tablet") {
        baseArray = Array.isArray(jsonTabletMbbPlans) ? jsonTabletMbbPlans : [];
    } 
    else if (device === "fixedplans") {
        baseArray = Array.isArray(jsonFixedPlans) ? jsonFixedPlans : [];
    }

    // Apply filtering ONLY on the correct baseArray
    if (proposition) {
        let key = device !== "fixedplans" ? "Proposition_Name" : "sPropoName";
        filterPlans = baseArray.filter(plan => plan.propArray[key] === proposition);
    } 
    else {
        filterPlans = [...baseArray];
    }

    // Reset pagination  
    currPage = 0;

    //   fresh plans for the active device only
    renderAllPlans(device);
    showPage(currPage, device);
} 
			

