            function renderAllPlans(device) {
                const $container = $(`.availableplansheadingcontainer1[data-device="${device}"] .plancontainer`);
                $container.empty();
                filterPlans.forEach((plan) => {
                    let dataEntitlement = "";
                    let dataNumberPart = "";
                    let dataTextPart = "";
                    let planCode = "";
                    let PlanPriceIncGst = "";
                    let PlanName = "";
                    let downloadSpeed = "";
                    let uploadSpeed = "";
                    let sCompType = "";       //dhana_fixedplans
                    let speedBannerHtml = "";      //dhana
                    let sCrtitcalinfoblock = ""; //vinay
                    let cispdfdetail = ""; //vinay


                    if (device === "mobile" || device === "tablet") {
                        planCode = plan?.propArray?.Plan_Code;
                        PlanPriceIncGst = plan?.propArray?.Plan_Price_Inc_Gst;
                        PlanName = plan?.propArray?.Plan_Name;
                        dataEntitlement = plan?.propArray?.Data_Entitlement || "";
                    } else if (device === "fixedplans") {
                        planCode = plan?.propArray?.sPlanCode;
                        PlanPriceIncGst = plan?.propArray?.sPlnPriceInGST;
                        PlanName = plan?.propArray?.sPlanName;
                        downloadSpeed = plan?.propArray?.sDwldSpeed || "0Mbps";
                        uploadSpeed = plan?.propArray?.sUpdSpeed || "0Mbps";
                        dataEntitlement = plan?.propArray?.sData_Entlemnt || "";
                        sCompType = plan?.propArray?.sCompType || ""; //Dhana

                        // banner only for fixedplans - Speed Boost Eligible
                        if (sCompType === "Speed Boost Eligible") {
                            speedBannerHtml = `
                                <div class="speed-upgrade-banner">
                                    Speed upgrade eligible
                                </div>`;
                        }
                    }

                    //vinay: added for CIS requirement
                    if(plan.propArray.PlanCISDetails) {
                        cispdfdetail = `images/custom/CIS/${plan.propArray.PlanCISDetails}`;
                    }
                    if (cispdfdetail) {
                        sCrtitcalinfoblock = `<div class="criticalinfoSummary">
                                <div><a id="criticalinfolink" href="${cispdfdetail}" target="_blank" rel="noopener" class="Paragraph-Body2-Underline">Critical Information Summary</a></div>
                                <!--<div><a id="rateandcharges" href="nolink" class="Paragraph-Body2-Underline">Rates and Charges</a></div>-->
                            </div>`;
                        }
                    //vinay: added for CIS requirement ended
                        
                        // Normalize entitlement
                        if (dataEntitlement && dataEntitlement.trim() !== "") {
                            // Extract numeric and text parts
                            const matchNumber = dataEntitlement.match(/\d+/);
                            const matchText = dataEntitlement.match(/[a-zA-Z]+/);
                        
                            dataNumberPart = matchNumber ? matchNumber[0] : "00";
                            dataTextPart = matchText ? matchText[0] : "GB";
                        } else {
                            // if entitlement missing
                            dataNumberPart = "00";
                            dataTextPart = "GB";
                        }
                    const html = `<div data-plan-code="${planCode}" class="availableplansdetailContainers">
                                           <div class="section1">
                                               <div class="part1 planverticaldivider">
                                                   <div class="value1 Heading-H1-strong"><span id="datavalue">${dataNumberPart}</span></span><span id="data" class="ParagraphBody2Strong">${dataTextPart}</span></div>
                                               </div>
                                               <div class="part2">
                                                   <div class="pricedetails">
                                                       <!-- <div class="value1 strikethrough strikethroughpart2"><span>$</span><span id="permonthvalue">${plan.propArray.PerMonth_Value}</span></div> --!>
                                                       <div class="value1 Heading-H1-strong"><span id="permonthoffervalue" class="ParagraphBody2Strong">$</span><span id="data" class="Heading-H1-strong">${formatNumber(PlanPriceIncGst)}</span></div>
                                                       <div class="ParagraphBody2">per month</div>
                                                   </div>
                                               </div>
                                           </div>
                                           ${speedBannerHtml}  <!-- will only render for eligible fixed plans -->
                                           <div class="plandetails">
                                               <div class="heading5 plannameclass" id="palanname">${PlanName}</div>
                                           </div>
                                           <div class="plandetailsitemsmain">
                                               <div class="plandetailsitems">
                                                            <!-- Typical evening speeds block (only for fixedplans) -->
                                                            <div class="plandetailsitemsrow typicalspeed">
                                                              <div class="value ParagraphBody2">Typical evening speeds (7pm-11pm)</div>
                                                            </div>
                                                            <div class="plandetailsitemsrow download row">
                                                              <!--<div><img src="images/custom/vha-scj-Success_24_24.svg" /></div> -->
                                                              <div class="ParagraphBody2Strong col-1">Download</div>
                                                              <div class="value ParagraphBody2 col-1">${downloadSpeed}</div>
                                                            </div>
                                                            <div class="plandetailsitemsrow upload row">
                                                             <!-- <div><img src="images/custom/vha-scj-Success_24_24.svg" /></div> -->
                                                              <div class="ParagraphBody2Strong col-1">Upload</div>
                                                              <div class="value ParagraphBody2 col-1">${uploadSpeed}</div>
                                                            </div>

                                                   <div class="plandetailsitemsrow">
                                                       <div class="tick-16"><img src="images/custom/vha-scj-Success_24_24.svg" /></div> 
                                                       <!--<div><img src="tick.webp"/></div>-->
                                                       <div class="ParagraphBody2Strong">Contract type</div>
                                                       <div id="nationalcalls " class="value ParagraphBody2">${plan.propArray.Contract_Type}</div>
                                                   </div>
                                                   <div class="plandetailsitemsrow national-calls">
                                                       <div class="tick-16"><img src="images/custom/vha-scj-Success_24_24.svg" /></div> 
                                                       <!--<div><img src="tick.webp"/></div>-->
                                                       <div class="ParagraphBody2Strong">National calls</div>
                                                       <div id="nationalcalls " class="value ParagraphBody2">${plan.propArray.National_Call}</div>
                                                   </div>
                                                   <div class="plandetailsitemsrow national-sms">
                                                       <div class="tick-16"><img src="images/custom/vha-scj-Success_24_24.svg" /></div> 
                                                       <!--<div><img src="tick.webp"/></div>-->
                                                       <div class="ParagraphBody2Strong">National SMS</div>
                                                       <div id="nationalsm" class="value ParagraphBody2">${plan.propArray.National_SMS}</div>
                                                   </div>
                                                   <div class="plandetailsitemsrow idd-zone1">
                                                       <div class="tick-16"><img src="images/custom/vha-scj-Success_24_24.svg" /></div> 
                                                       <!--<div><img src="tick.webp"/></div>-->
                                                       <div class="ParagraphBody2Strong">IDD Zone 1</div>
                                                       <div id="idzone1" class="value ParagraphBody2">${plan.propArray.IDD_Zone_1}</div>
                                                   </div>
                                                   <div class="plandetailsitemsrow idd-zone2">
                                                     <div class="tick-16"><img src="images/custom/vha-scj-Success_24_24.svg" /></div> 
                                                       <!--<div><img src="tick.webp"/></div>-->
                                                       <div class="ParagraphBody2Strong">IDD Zone 2</div>
                                                       <div id="idzone2" class="value ParagraphBody2">${plan.propArray.IDD_Zone_2}</div>
                                                   </div>

                                               </div>
                                               <div class ="mbPlanCounter displaynone">
                                                    <button class = "btn minus">-</button>
                                                    <input type="text" id="count" class="planCount" value = "1" readonly>
                                                    <button class = "btn plus">+</button>
                                               </div>
                                               <div class="SelectbuttonContainer">
                                                   <button data-plan-code="${plan.propArray.Plan_Code}" class="vha-scj-select-plan ParagraphBody1">Select</button>
                                               </div>
                                               ${sCrtitcalinfoblock}
                                               <div class="End"></div>
                                               </div>`;
                    $container.append(html);
                });

                //  Hide rows if device is NOT voice
                if (device !== 'mobile') {
                    $container.find('.national-calls, .national-sms, .idd-zone1, .idd-zone2').hide();
                }

                // HIde rows for fixed
                if (device === 'fixedplans') {
                    // Show ONLY typicalspeed + download + upload
                    $container.find('.plandetailsitemsrow').not('.typicalspeed, .download, .upload').hide();

                    // Make sure the speeds rows are visible
                    $container.find('.typicalspeed, .download, .upload').show();
                } else {
                    $container.find('.typicalspeed, .download, .upload').hide();
                }
                totalItems = filterPlans.length;
                totalPages = Math.ceil(totalItems / itemsPerPage);
            }

            function showPage(page, device) {

                const $container = $(`.availableplansheadingcontainer1[data-device="${device}"] .plancontainer`);
                const $plans = $container.find(".availableplansdetailContainers");

                const start = page * itemsPerPage;
                const end = Math.min(start + itemsPerPage, totalItems);

                currPage = page;
                // Show Pagination Info
                const displayStart = start + 1;
                const displayEnd = end;
                $(`.availableplansheadingcontainer1[data-device="${device}"] .pagination-info`).text(`${displayStart} - ${displayEnd} of ${totalItems} items`);

                $plans.hide();
                $plans.slice(start, end).show();

                //Disable buttons
                /*$(".carousel-nav-prev").prop("disabled", page === 0);
                $(".carousel-nav-next").prop("disabled", page >= totalPages - 1);*/
                $(`.availableplansheadingcontainer1[data-device="${device}"] .carousel-nav-prev`).prop("disabled", page === 0);
                $(`.availableplansheadingcontainer1[data-device="${device}"] .carousel-nav-next`).prop("disabled", page >= totalPages - 1);
				//Marvin : Added for CM-10044
				if($('.scj-tab-active')[0].outerText === "Fixed"){
					$(`.vha-scj-fxtabs-wrapper .current-plan-warning-box`).addClass("displaynone");
				}
            }

            function checkQliNum() {
                //if (sProdConId !== sQuoteId) //Jeeten: 17-dec Added to skip from Prod Config
                //if (resumeQuote !== "Y")
				if(productConfig !== "Y")
                { //reset cuurentrli
                    for (let i = 0; i < currentRLI.length; i++) {
                        let rli = currentRLI[i];
                        rli.Id = `QLI-${Math.floor(1000 + Math.random() * 9000)}`;
                    }
                }

            }

            function canAddMorePlans() {
                let existingServicesCount = scJson.QuoteHeader.ExistingCustDtls.ActiveServices;
                let newServicesCount = scJson.QuoteHeader.RootItem.length;
                return (existingServicesCount + newServicesCount + selectedPlans.length) < 10;
            }

            //dhana: plans data
            function createPlanObj(src) {
                const isFixed = !!(src?.sPlanCode || src?.sPropoName); // detect fixed schema
                return {
                    Type: "Plan",
                    Action: "Add",
                    Name: isFixed ? src.sPlanName : src.Plan_Name,
                    Code: isFixed ? src.sPlanCode : src.Plan_Code,
                    ProdIntegrationId: isFixed ? (src.sProdCode || "") : src.Product_Code,
                    Price: isFixed
                     ? (src.sPlnPriceInGST ?? src.sPlnPriceExGST ?? "")
                     : src.Plan_Price_Inc_Gst,
                    PaymentTerm: isFixed
                     ? (src.sContType || src.sContract || "")
                     : src.Contract_Type,
                    VoucherAmount: isFixed ? (src.sVouAmt || "") : src.Voucher_Amount,
                    PlanJourneyType: isFixed
                     ? (src.sPlanType || src.sType || "")
                     : src.Type,
                    DownloadSpeed: isFixed ? String(parseInt(src.sDwldSpeed, 10) || "") : "", //Dhana_CM-8161
                    UploadSpeed:isFixed ? String(parseInt(src.sUpdSpeed, 10) || "") : "", //Dhana_CM-8161
                    NetworkIdent: isFixed ? src.sNetIdent : "", //Dhana_CM-8161
                    Tab: isFixed ? "FixedTab" : "MobileTab",
                    Descr: "",
                    PlanType: isFixed ? src.Plan_Type : ""
                };
            }

