            function formatDateRange(start, end) {
                const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                const format = d => {
                    let [month, day, year] = d.split("/");
                    return `${day} ${months[+month - 1]} ${year}`;
                };
                return `${format(start)} - ${format(end)}`;
            }

