            function compatabilityCheckWF(deviceCode, planCode) { //dhana 261225
                let check = "";
                let ser = SiebelApp.S_App.GetService("Workflow Process Manager");
                let Inputs = SiebelApp.S_App.NewPropertySet();
                Inputs.SetProperty("ProcessName", "VHA SSJ Product Info Process");
                Inputs.SetProperty("PlanCd", planCode);
                Inputs.SetProperty("DevCd", deviceCode);
                if (currentRLI[0].SrvType === "Upgrade Service"){
                    Inputs.SetProperty("SrcType", "Upgrade");
				}
                else{
                    Inputs.SetProperty("SrcType", "Connect with device");
				}
                Inputs.SetProperty("Type", "ValCd");
                let Output = ser.InvokeMethod("RunProcess", Inputs);
                if (Output) {
                    check = Output.childArray[0].propArray.NumRec;
                }
                return check;
            }

            function compatabilityCheckValidation(deviceName, planName) { //dhana
                $('#compat-warning').removeClass("displaynone");
                showCartItemExceededDialog("Cart item exceeded", "There are selected items that are incompatible with the Proposition/Plan selected. Please remove some items to proceed.");
                const $anchor = $('#vha-ssj-warning');

                if ($anchor.length === 0) {
                    console.warn('Warning container #vha-ssj-warning not found.');
                    return false; // couldn't show
                }
                let tab = "";
                if (ActiveTab === "mobile") {
                    tab = "Mobile";
                } else if (ActiveTab === "tablet") {
                    tab = "Tablet";
                } else if (ActiveTab === "fixedModem") {
                    tab = "Fixed";
                }else if(ActiveTab==="accessory"){//vivek CM-10131
					tab = "Accessories";
				}else if(ActiveTab==="Wearble"){//vivek CM-10131
					tab = "Wearables";
				}
                // 👉 Do NOT hide the anchor here if you want the inserted banner to be visible & positioned correctly.
                // $('#vha-ssj-warning').addClass("displaynone"); // REMOVE or move this elsewhere if really needed

                // Build the warning HTML with a stable id to avoid duplicates
                const html = `
                <div id="compat-warning" class="main-validations-warning-box" role="alert" aria-live="polite">
                  <span class="warning-icon" aria-hidden="true">
                    <img src="images/custom/menu-icons/exclamationCircleIcon.svg" alt="Warning" />
                  </span>
                  <span class="warning-text">
                    There are selected items that are incompatible with the Proposition/Plan selected.
                  </span>
                  <ul class="warning-details">
                    <li>${tab} - ${planName}, ${deviceName}</li>
                  </ul>
                </div>
              `;

                const existing = document.getElementById('compat-warning');
                if (existing) {
                    existing.outerHTML = html; // replace existing block (prevents duplicates)
                } else {
                    $anchor.after(html); // insert once after the anchor
                }

                return true; // shown
            }

            function showCartItemExceededDialog(title, msg) { //dhana /* renuka CM-6872 */
                var html = `<div id="VHA-infomsg-dialog">
                            <div class="vha-header-infomsg">
                                <h3>${title}</h3>
                                <span class="validation-popup-close">
                                <img src="images/custom/menu-icons/Cross_20x20.svg"/> 
                                </span>					
                            </div>
                            <div id="step2divider1" class="validationdividertop"></div>
                                <span class="vha-body"> ${msg} </span>
                            <div id="step2divider2" class="validationdividerbottom"></div>
                            <div id="divider2bottom" class ="dividerbottom"></div>
                        </div>`;
                $("#VHA-infomsg-dialog").remove();
                // remove any existing dialog
                $("body").append(html);
                var dialog = $("#VHA-infomsg-dialog").dialog({
                    modal: true,
                    resizable: false,
                    width: 650,
                    height: "auto",
                    title: "",
                    dialogClass: "vha-dialog",
                    open: function () {
                        $(".ui-dialog-titlebar").hide();
                        // hide default title bar
                    },
                    buttons: (title === "Update your selection") ? {
                        "Go back": function () {
                            $(this).dialog("close");
                        },
                        "OK, continue": function () {
                            addToCartValidationChecks();
                            $(this).dialog("close");
                        }
                    } : {
                        "Close": function () {
                            $(this).dialog("close");
                        }
                    },
                    create: function () {
                        var buttons = $(this).parent().find(".ui-dialog-buttonpane button");
                        if (title === "Update your selection") {
                            buttons.eq(0).addClass("btn-go-back");
                            buttons.eq(1).addClass("btn-ok-continue");
                        } else {
                            buttons.eq(0).addClass("btn-close");
                        }
                    }
                });
                 // $("#VHA-infomsg-close-btn").off("click").on("click", function () {
                //     dialog.dialog("close");
                //     $("#VHA-infomsg-dialog").remove();
                // });
                                    
                    $(".btn-go-back").off("click").on("click", function() {
                            allowAddToCart = false;
                            $("#VHA-infomsg-dialog").remove();
                        });
                    
                        // OK, Proceed button
                        $(".btn-ok-continue").off("click").on("click", function() {
                            allowAddToCart = true;
                            $("#VHA-infomsg-dialog").remove();
                            $(".vha-scj-step3-nxt").trigger("click"); // re-trigger Add to Cart
                        });

                $(".validation-popup-close")
                .off("click")
                .on("click", function () {
                    dialog.dialog("close");
                    $("#VHA-infomsg-dialog").remove();
                });
            }
            function isFixedServiceLimitExceeded() { //dhana_Updated_CM-7657

                let fixedCount = scJson.QuoteHeader.RootItem.filter(item =>
                    item.SrvType?.trim().toLowerCase() === "new service" &&
                    (
                        (item.FixedPlanItem && item.FixedPlanItem.Name) ||     
                        (item.FixedmodemItem && item.FixedmodemItem.length > 0)  
                    )
                ).length;

                //Dhana_CM-7967
                const existingArr = scJson?.QuoteHeader?.ExistingServices?.[0];

                const existingFixedCount = existingArr?.filter(svc => {
                    const updates = Array.isArray(svc?.update) ? svc.update : [];

                    return updates.some(u =>
                        typeof u?.FixedPlanItem?.Name === "string" &&
                        u.FixedPlanItem.Name.trim().length > 0
                    );
                }).length;

                //Jeeten: Check if fixed service is in edit mode.
                let editingfixedService = scJson.QuoteHeader.RootItem.filter(item =>
                    item.CartStatus?.trim().toLowerCase() === "updateinprogress" &&
                    (
                        (item.FixedPlanItem && item.FixedPlanItem.Name) ||
                        (item.FixedmodemItem && item.FixedmodemItem.length > 0)
                    )
                ).length;
                
                 //Dhana_CM-7967
                let currentHasFixed = 0;
                
                if (currentRLI[0]?.FixedPlanItem?.Name) {
                    currentHasFixed += 1;
                }
                
                if (Array.isArray(currentRLI[0]?.FixedmodemItem)) {
                    currentHasFixed += currentRLI[0].FixedmodemItem.length;
                }
                //Dhana_CM-7967
                return ((fixedCount >= 1 || existingFixedCount >=1 ) && currentHasFixed >=1 && editingfixedService != 1 );
            }

            function addToCartValidationChecks(data) { //dhana
                $('#compat-warning').removeClass("displaynone");
                let msg = "";
                let warningtext = "";
                let title = "";

                if (data === "exceedServices") {
                    warningtext = "Adding these items to cart will exceed the allowable number of services for this billing account.";
                    msg = "Adding the selected items to cart will exceed the allowable number of services for this billing account. Please remove some items to proceed.";
                    title = "Cart item exceeded";
                    showCartItemExceededDialog(title, msg);
                }
                else if (data === "exceedServiceCount") {
                    warningtext = "Adding these items to cart will exceed the allowable number of payment plans for this billing account.";
                    msg = "Adding the selected items to cart will exceed the allowable number of payment plans for this billing account. Please remove some items to proceed.";
                    title = "Update your selection";
                    showCartItemExceededDialog(title, msg);
                    // return allowAddToCart; dhana_commented
                }
                else if (data === "exceedFixedFWA") {
                    warningtext = "Adding more than 1 fixed and FWA services into a quote is not allowed.";
                }
                const $anchor = $('#vha-ssj-warning');

                if ($anchor.length === 0) {
                    console.warn('Warning container #vha-ssj-warning not found.');
                    return false;
                }

                let tab = "";
                if (ActiveTab === "mobile") {
                    tab = "Mobile";
                } else if (ActiveTab === "tablet") {
                    tab = "Tablet";
                } else if (ActiveTab === "fixedModem") {
                    tab = "Fixed";
                }

                // Build warning block
                let html = `
        <div id="compat-warning" class="main-validations-warning-box" role="alert" aria-live="polite">
            <span class="warning-icon" aria-hidden="true">
                <img src="images/custom/menu-icons/exclamationCircleIcon.svg" alt="Warning" />
            </span>
            <span class="warning-text">
                ${warningtext}
            </span>
        </div>
    `;

                const existing = document.getElementById('compat-warning');
                if (existing) {
                    existing.outerHTML = html; // replace existing block
                } else {
                    $anchor.after(html); // insert once after the anchor
                }

                //Append selected items list inside the warning container
                const $warningText = $('#compat-warning .warning-text');

                if (currentRLI && currentRLI.length > 0) {
                    let listHtml = "<ul class='selected-items-list'>";
                    currentRLI.forEach(item => {

                        let mainLineParts = [];
                        let tabName = ""; // will be set when we push the first relevant value

                        const pushWithTab = (value, label) => {
                            if (value) {
                                if (!tabName)
                                    tabName = label; // set tab on first push
                                mainLineParts.push(value); // push the actual part
                            }
                        };

                        // Plans
                        const mobilePlan = item.PlanItem?.Name || "";
                        const fixedPlan = item.FixedPlanItem?.Name || "";

                        // Devices
                        const mobileDevice = item.DeviceItem?.[0]?.Item__Name || "";
                        const tabletDevice = item.TabletItem?.[0]?.UI__Source_Product_Name || "";
                        const fixedDevice = item.FixedmodemItem?.[0]?.FixedModem__Name || "";

                        // Push with labels
                        pushWithTab(mobilePlan, "Mobile");
                        pushWithTab(fixedPlan, "Fixed");
                        pushWithTab(mobileDevice, "Mobile");
                        pushWithTab(tabletDevice, "Tablet");
                        pushWithTab(fixedDevice, "Fixed");

                        const mainLine = mainLineParts.join(", ");
                        if (mainLine) {
                            // if tabName is still empty, fall back to "Unknown"
                            listHtml += `<li>${tabName || "Unknown"} - ${mainLine}</li>`;
                        }

                        // Accessories
                        if (item.AccItem && item.AccItem.length) {
                            item.AccItem.forEach(acc => {
                                listHtml += `<li>Accessories - ${acc.Accessory__Name}</li>`;
                            });
                        }

                        // Wearables
                        if (item.SecondaryItem && item.SecondaryItem.length) {
                            item.SecondaryItem.forEach(wear => {
                                listHtml += `<li>Wearables - ${wear.Item__Name}</li>`;
                            });
                        }
                    });
                    listHtml += "</ul>";

                    $warningText.append(listHtml);
                }

                return true;
            }

            function checkCartItemLimit() { //dhana
                let totalItems = 0;

                if (currentRLI && currentRLI.length > 0) {
                    currentRLI.forEach(item => {
                        // Count plans
                        if (item.PlanItem?.Name)
                            totalItems += 1;
                        if (item.FixedPlanItem?.Name)
                            totalItems += 1;

                        // Count devices
                        if (item.DeviceItem && item.DeviceItem.length > 0)
                            totalItems += item.DeviceItem.length;
                        if (item.TabletItem && item.TabletItem.length > 0)
                            totalItems += item.TabletItem.length;
                        if (item.FixedmodemItem && item.FixedmodemItem.length > 0)
                            totalItems += item.FixedmodemItem.length;

                        // Count accessories
                        if (item.AccItem && item.AccItem.length > 0)
                            totalItems += item.AccItem.length;
                        if (item?.fixedAccItem && item?.fixedAccItem.length > 0) //Dhana_18feb
                            totalItems += item?.fixedAccItem.length;

                        // Count wearables
                        if (item.SecondaryItem && item.SecondaryItem.length > 0)
                            totalItems += item.SecondaryItem.length;
                    });
                }

                return totalItems;
            }

            function removeDuplicatePlans(jsonAllplans) { //dhana- CM-6359
                // 1) Group by Plan_Code
                const groupedPlans = {};
                (Array.isArray(jsonAllplans) ? jsonAllplans : []).forEach(obj => {
                    const code = obj?.propArray?.Plan_Code;
                    if (!code)
                        return;
                    (groupedPlans[code] ??= []).push(obj);
                });

                // 2) Determine preference based on SrvType (SAFE)
                const srvType = currentRLI?.[0]?.SrvType ?? '';
                const isUpgrade = String(srvType).trim().toLowerCase() === 'upgrade service';
                const preferType = isUpgrade ? 'UniqueRPC' : 'UniquePlan';

                // Helpers
                const normalizeType = (t) => String(t || '').trim().toLowerCase();
                const normalizeTypeRelaxed = (t) => normalizeType(t).replace(/\s+/g, ''); // 'Unique RPC' -> 'uniquerpc'

                // Prefer 'UniqueRPC' for upgrade, else 'UniquePlan' (case/space tolerant)
                const isPreferredType = (obj) => {
                    const t = obj?.propArray?.Type;
                    return (
                        normalizeType(t) === normalizeType(preferType) ||
                        normalizeTypeRelaxed(t) === normalizeTypeRelaxed(preferType));
                };

                // 3) Selection rule per Plan_Code
                const pickBestForCode = (records) => {
                    if (!Array.isArray(records) || records.length === 0)
                        return undefined;
                    const preferred = records.find(isPreferredType);
                    return preferred ?? records[0]; // Fallback: preserve original order
                };

                // 4) Build outputs
                const removedRecords = [];
                const dedupedPlans = [];

                // (Optional) diagnostics
                // console.log('Grouped plan codes:', Object.keys(groupedPlans));
                // console.log('Group sizes:', Object.entries(groupedPlans).map(([code, arr]) => ({ code, size: arr.length })));
                // console.log('srvType:', srvType, 'preferType:', preferType);

                try {
                    Object.values(groupedPlans).forEach((records) => {
                        if (!Array.isArray(records) || records.length === 0)
                            return;

                        if (records.length === 1) {
                            dedupedPlans.push(records[0]);
                            return;
                        }

                        const best = pickBestForCode(records);
                        dedupedPlans.push(best);

                        // Collect removed ones
                        records.forEach(r => {
                            if (r !== best)
                                removedRecords.push(r);
                        });
                    });

                    // console.log('Removed duplicates count:', removedRecords.length);
                } catch (e) {
                    console.error('[DIAG] Exception inside loop:', e);
                }

                // IMPORTANT: return the deduped list (Pattern 1)
                return dedupedPlans;
            }

            function hasPendingSelectionIn(tabKey) { //dhana
                // Map tab keys to the DOM sections we render
                const map = {
                    mobile: {
                        deviceCards: '.vha-scj-mobiletab .carosuel-main[data-id="mobile"] .vha-scj-card.selected-card',
                        plans: '.availableplansheadingcontainer1[data-device="mobile"] .selected-card-plan'
                    },
                    tablet: {
                        deviceCards: '.vha-scj-tablets-tab .carosuel-main[data-id="tablet"] .vha-scj-card.selected-card',
                        plans: '.availableplansheadingcontainer1[data-device="tablet"] .selected-card-plan'
                    },
                    fixed: {
                        // Modem/device selection + fixed plans selection
                        deviceCards: '.vha-scj-st3-fx-devices .carosuel-main[data-id="fixedModem"] .vha-scj-card.selected-card',
                        plans: '.availableplansheadingcontainer1[data-device="fixedplans"] .selected-card-plan'
                    }
                };

                const cfg = map[tabKey];
                if (!cfg)
                    return false;

                const hasDevice = $(cfg.deviceCards).length > 0;
                const hasPlan = $(cfg.plans).length > 0;

                return hasDevice || hasPlan;
            }

            function renderGlobalWarning(msg, { //dhana
            } = {}) {
                const $box = $('#vha-ssj-warning');
                if ($box.length === 0) {
                    console.warn('Warning container #vha-ssj-warning not found.');
                    return;
                }

                // Build markup if not present
                const html = `
                <div class="header-validations-warning-box">
                <span class="warning-icon">
                    <img src="images/custom/menu-icons/exclamationCircleIcon.svg" alt="Warning"/>
                </span>
                <span class="warning-text"></span>
                </div>
            `;
                if ($box.find('.header-validations-warning-box').length === 0) {
                    $box.html(html);
                }

                // Apply dynamic colors to #vha-ssj-warning
                $('#vha-ssj-warning').css({
                    backgroundColor: '#FEE7E6', // light red background
                    borderColor: '#CE0000', // dark red border
                    borderStyle: 'solid', // ensure border style
                    borderWidth: '1px' // ensure border width
                });

                // Set text and show
                $box.removeClass('displaynone')
                .find('.warning-text').text(msg);

                $box.attr({
                    role: 'alert',
                    'aria-live': 'polite'
                });

            }

            function showTabSwitchWarning(tabKey) { //dhana
                let msg;

                if (tabKey === 'mobile') {
                    msg = 'Please first add selected items to the cart in mobile phones or deselect.';
                } else if (tabKey === 'tablet') {
                    msg = 'Please first add selected items to the cart in Tablets & MBB or deselect.';//10637 chnge text
                } else { // fixed
                    msg = 'Please first add selected items to the cart in fixed plans & devices or deselect.';
                }

                renderGlobalWarning(msg);
				bannerFocus(); //Sowmya - 10519
                //sowmya -8373
                document.querySelectorAll('.header-validations-warning-box').forEach(box => {
                    const text = (box.textContent || '').toLowerCase();
                    box.classList.toggle('align-center', text.includes('please first add'));
                  });
            }

            function blockIfPendingSwitchTo(targetTabKey, e) { //dhana
                // Check the other two keys first, in a consistent order
                const keys = ['mobile', 'tablet', 'fixed'].filter(k => k !== targetTabKey);

                // If any 'other' tab has selections, block the switch and warn for that tab
                const pendingTab = keys.find(k => hasPendingSelectionIn(k));
                if (pendingTab) {
                    e && e.preventDefault();
                    e && e.stopPropagation();
                    showTabSwitchWarning(pendingTab);
                    return true;
                }
                return false;
            }

            function resetWarningThemeToDefault() { //dhana
                const $box = $('#vha-ssj-warning');
                if ($box.length === 0)
                    return;

                // Remove inline styles to fall back to CSS defaults
                $box.css({
                    backgroundColor: '#fef7e0',
                    borderColor: '#f26522'
                });
            }

            function formatNegativeCurrency(value) { //dhana_CM-7530
                const n = typeof value === 'string'
                    ? Number(value.replace(/[^\d.-]/g, ''))
                    : Number(value);

                if (Number.isNaN(n)) return '$0.00';

                const sign = n < 0 ? '-$' : '$';
                return sign + Math.abs(n).toFixed(2);
            }

