            function getVisibleProductCodes() {
                const productCodes = [];
                if (ActiveTab === 'mobile' || ActiveTab === 'tablet' || ActiveTab === 'fixedModem') {
                    $(`.carosuel-main[data-id="${ActiveTab}"] .vha-scj-card`).each(function () {
                        if ($(this).is(":visible")) {
                            let productId = $(this).attr("data-product-id");
                            let devicetype = $(this).attr("data-devicetype");
							//Marvin: Added for CM-9502
							let planType = $(this).attr("data-plantype");
                            if (devicetype === "Connect with device" || devicetype === "UniqueDevice") {
                                devicetype = "UniqueDevice";
                            } else if (devicetype === "Upgrade RRP on Installment" || devicetype === "RRPInsUniqueDevice") {
                                devicetype = "RRPInsUniqueDevice";
                            } else if (devicetype === "Upgrade to New plan" || devicetype === "UpgUniqueDevice") {
                                devicetype = "UpgUniqueDevice";
                            }

                            if (productId) {
                                productCodes.push({
                                    productId,
                                    devicetype,
									planType
                                });
                            }
                        }
                    });
                } else {
                    $(`.carosuel-main[data-id="${ActiveTab}"] .vha-scj-card`).each(function () {
                        if ($(this).is(":visible")) {
                            const productId = $(this).attr("data-product-id");
                            if (productId) {
                                productCodes.push(productId);
                            }
                        }
                    });
                }

                return productCodes;
            }

            function updateVisibleStockText(stockMap, deliverydateMap, shipmentdateMap) {

                $(`.carosuel-main[data-id="${ActiveTab}"] .vha-scj-card:visible`).each(function () {
                    const $card = $(this);
                    const productId = $card.attr("data-product-id");
                    const dataProdId = $card.attr("data-product-id");
                    let status = stockMap[productId];
                    const deliverydate = deliverydateMap[productId];
                    const shipmentDate = shipmentdateMap[productId]; //Marvin: Added for CM-6132
                    stockcheckflg = "N"; //10269 sabeeha

                    if (!status) {
                        status = stockMap[dataProdId];
                    }
                    if (status.length > 0 && status !== undefined) {
                        const $stockContainer = $card.find('.vha-scj-stock');
                        const $statusEl = $card.find('.vha-scj-stock-status');
                        let statusText = '';
                        //$card.find('.vha-scj-delivery-date').text(deliverydate);//Marvin: Remove for CM-6132
                        switch (status) {
                        case 'Available':
                            statusText = 'In Stock';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated delivery date";
							if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								if( deliverydate =="" || deliverydate ==null){ //7291 sabeeha
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								}else{
									$card.find('.vha-scj-delivery-date').text(deliverydate); //CM-6132
								}
								$card.find('.vha-delivery-div').removeClass("displaynone"); //Jeeten: CM-6470
							}
                            break;
                        case 'Out of Stock':
                            statusText = 'Out of Stock';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated shipping date";
							if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								if( shipmentDate =="" || shipmentDate ==null){ //7291 sabeeha
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								}else{
									$card.find('.vha-scj-delivery-date').text(shipmentDate); //CM-6132
								}
								$card.find('.vha-delivery-div').removeClass("displaynone"); //Jeeten: CM-6470
							}
                            break;
                        case 'Non-Orderable':
                            statusText = 'Out of Stock';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated shipping date";
                            if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								if( shipmentDate =="" || shipmentDate ==null){ //7291 sabeeha
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								}else{
									$card.find('.vha-scj-delivery-date').text(shipmentDate); //CM-6132
								}
								$card.find('.vha-delivery-div').removeClass("displaynone");//Marvin - CM-7162
							}
                            break;
                        case 'Back Order':
                            statusText = 'Back-order';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated shipping date";
                            if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								if( shipmentDate =="" || shipmentDate ==null){ //7291 sabeeha
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								}else{
									$card.find('.vha-scj-delivery-date').text(shipmentDate); //CM-6132
								}
								$card.find('.vha-delivery-div').removeClass("displaynone");//Marvin - CM-7162
							}
                            break;
                        case 'Low Stock':
                            statusText = 'Low Stock';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated delivery date";
							if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								if( deliverydate =="" || deliverydate ==null){ //7291 sabeeha
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								}else{
									$card.find('.vha-scj-delivery-date').text(deliverydate); //CM-6132
								}
								$card.find('.vha-delivery-div').removeClass("displaynone"); //Jeeten: CM-6470
							}
                            break;
						case "Stock check failed" : //7291 sabeeha
							statusText = 'Stock check failed';
                            $card.find('.vha-delivery-div')[0].firstChild.nodeValue = "Estimated shipping date";
							if(stockCheckpostcode.length > 0){//Marvin : Added for CM-9940
								//if( shipmentDate =="" || shipmentDate ==null){
									$card.find('.vha-scj-delivery-date').text("unknown"); 
								/*}else{
									$card.find('.vha-scj-delivery-date').text(shipmentDate); //CM-6132
								}*/
								$card.find('.vha-delivery-div').removeClass("displaynone");//Marvin - CM-7162
							}
                            break;
                        default:
                            statusText = '';
                        }
                        //Marvin: Added for CM-5584
                        if (statusText === "Out of Stock" || statusText === "Stock check failed") {//7291 sabeeha
                            if ($card.find('.stock-check-success')) {
                                $card.find('.stock-check-success').removeClass('stock-check-success').addClass('stock-check-NO')
                            }
                            if ($card.find('.stock-check-LS')) {
                                $card.find('.stock-check-LS').removeClass('stock-check-LS').addClass('stock-check-NO')
                            }
                        } else if (statusText === "Low Stock") {
                            if ($card.find('.stock-check-success')) {
                                $card.find('.stock-check-success').removeClass('stock-check-success').addClass('stock-check-LS')
                            }
                            if ($card.find('.stock-check-NO')) {
                                $card.find('.stock-check-NO').removeClass('stock-check-NO').addClass('stock-check-LS')
                            }
                        } else if (statusText === "In Stock" || statusText === "Back-order") {
                            if ($card.find('.stock-check-LS')) {
                                $card.find('.stock-check-LS').removeClass('stock-check-LS').addClass('stock-check-success')
                            }
                            if ($card.find('.stock-check-NO')) {
                                $card.find('.stock-check-NO').removeClass('stock-check-NO').addClass('stock-check-success')
                            }
                        }
                        $statusEl.text(statusText);
                        $stockContainer.show();
                    } else {
                        $card.find('.vha-scj-stock')[0].style = "display: none";
                        //return;
                    }
                });
            }
