				let newAccStart = 0;
                let SiebMsg = SiebelApp.S_App.NewPropertySet();
                let Item1 = SiebelApp.S_App.NewPropertySet();
                let ListOfItem = "";
                let sRoot = "RootItem";
                let sItem = "Item";
                let ListOfRootItem = SiebelApp.S_App.NewPropertySet();
