            function popUpMsgSSJ(dataId, assetintegid) {
                let popupHtmlApply = `<div id="remPromoPopup" class="rempromocode-header-modal">
                        <div class="SSJ-cart-modal-header"><span class="SSJ-cart-modal-title">Are you sure you want to remove promocode on this service?</span>
                            <span class="rem-promo-close">&times;</span></div>
                            <div id="step2divider2" class="promodividerbottom"></div>
                            <div class="rem-promo-actions">
                                <button id="cancelBtn" class="btn btn-cancel">Cancel</button>
                                <button id="rempromobtn" class="btn btn-rempromo" data-id="` + dataId + `" ast-int-id="` + assetintegid + `">Yes, remove</button>
                            </div>
                        </div>`;
                $("body").append(popupHtmlApply);
                dialog = $("#remPromoPopup").dialog({
                    autoOpen: false,
                    zIndex: 10000,
                    resizable: false,
                    width: 650,
                    height: 230,
                    modal: true,
                });
                dialog.dialog("open");

                $("body").off('click').on("click", "#cancelBtn", function () {
                    $("#remPromoPopup").remove();
                }).on("click", '.rem-promo-close', function () {
                    $("#remPromoPopup").remove();
                }).on("click", "#rempromobtn", function () {
                    let btnDataId = $('#rempromobtn')[0].getAttribute("data-id");
                    let currExtService = "";
                    if (assetintegid) { //Jeeten: 19-dec
                        //GetPromoDetails(btnDataId,"",scJson.QuoteHeader.ExistingServices[0],"Modify",assetintegid);
                        currExtService = scJson.QuoteHeader.ExistingServices[0].filter(obj => obj.MSISDN === btnDataId)[0];
                        var idx = currExtService.update[0].offers.findIndex(off => off.TrigPromoCd);
                        currExtService.update[0].offers.splice(idx, 1);
                        $('#vha-existing-box-' + btnDataId + ' .item.promo').parent().remove();
                    } else {
                        //GetPromoDetails(btnDataId,"",scJson.QuoteHeader.RootItem,"New");
                        currExtService = scJson.QuoteHeader.RootItem.filter(obj => obj.Id === btnDataId)[0];
                        var idx = currExtService.offers.findIndex(off => off.TrigPromoCd);
                        currExtService.offers.splice(idx, 1);
                        $('#cart-container-' + btnDataId + ' .item.promo').parent().remove();
                    }
                    //Jeeten: 19-dec
                    $('#item-cust-sec' + btnDataId + ' .opt-drop').removeClass("promo-applied");
                    $(".rempromocode-header-modal").remove();
                    calcServiceTotal(`cart-container-` + btnDataId);
                }); //Marvin
            }
