            function UpdateOneTimeChargesTooltip() {
                const parseAmount = function (value) {
                    if (value === null || value === undefined) return 0;
                    const parsed = parseFloat(String(value).replace(/[^0-9.-]/g, ''));
                    return isNaN(parsed) ? 0 : parsed;
                };
                let oneTimeSubtotal = 0.00;
                const oneTimeDiscounts = 0.00;
                let totalPayoutAmount = 0.00;
                const existingServicesArray = scJson?.QuoteHeader?.ExistingServices?.[0] || [];
				if(scJson?.QuoteHeader?.ExistingServices?.[0] !== undefined && scJson?.QuoteHeader?.ExistingServices?.[0][0] !== undefined){//Marvin
                if (Array.isArray(existingServicesArray) && existingServicesArray.length > 0) {
                    existingServicesArray.forEach(service => {
                        if (service.update && Array.isArray(service.update) && service.update.length > 0) {
                            service.update.forEach(updateEntry => {
                                if (updateEntry.PayoutDevice && Array.isArray(updateEntry.PayoutDevice)) {
                                    updateEntry.PayoutDevice.forEach(payout => {
                                        totalPayoutAmount += parseAmount(payout.PayoutAmount ?? payout.Price ?? payout.payoutAmt);
                                    });
                                }
                            });
                        }
                    });
					}
                }
                let newDevelopmentCharges = parseAmount($('#newdevelopmentfx').text().trim());
                if (newDevelopmentCharges === 0.00) {
                    newDevelopmentCharges = parseAmount($('#newdevelopment').text().trim());
                }
                if (newDevelopmentCharges === 0.00) {
                    const rootItems = scJson?.QuoteHeader?.RootItem || [];
                    if (Array.isArray(rootItems) && rootItems.length > 0) {
                        const fixedService = rootItems.find(item =>
                            item.FixedPlanItem &&
                            typeof item.FixedPlanItem === 'object' &&
                            Object.keys(item.FixedPlanItem).length > 0
                        );
                        if (fixedService) {
                            newDevelopmentCharges = parseAmount(fixedService.NewDevelopmentCharge ?? fixedService.FixedPlanItem?.NewDevelopmentCharge);
                        }
                    }
                }
                oneTimeSubtotal = totalPayoutAmount + newDevelopmentCharges;
                $('.vha-ot-ch .tooltip-box .tooltip-row:nth-child(1) span:last-child').text('$' + formatNumber(oneTimeSubtotal.toFixed(2)));
                $('.vha-ot-ch .tooltip-box .tooltip-row:nth-child(2) span:last-child').text('-$' + formatNumber(oneTimeDiscounts.toFixed(2)));
            }
