            /*Jeeten: 26-feb-26*
             * Update Sales Quote Details via Business Service
             * @param {string} QuoteId - Quote/Order ID
             * @param {string} OUIjSId - OUI/JSI Item ID
             * @param {string} methodName - Method to invoke: "UpdateJSIdToSQ" or "RevertJSIdToSQ"
             * @param {function} callback - Optional callback function on success
             */
            function updateSQdetails(QuoteId, OUIjSId, methodName = "UpdateJSIdToSQ", callback = null) {
                try {
                    // Validate inputs
                    if (!QuoteId || !OUIjSId) {
                        console.warn("updateSQdetails: Missing required parameters - QuoteId:", QuoteId, "OUIjSId:", OUIjSId);
                        return false;
                    }

                    var bsService = SiebelApp.S_App.GetService("VF BS Process Manager");
                    if (!bsService) {
                        console.error("updateSQdetails: VF BS Process Manager service not available");
                        return false;
                    }

                    var psInputs = SiebelApp.S_App.NewPropertySet();
                    var psOutputs = SiebelApp.S_App.NewPropertySet();
                    
                    // Set service and method properties
                    psInputs.SetProperty("Service Name", "VHA Map JS Item Addr SQ Details BS");
                    psInputs.SetProperty("Method Name", methodName);
                    
                    // Set input parameters
                    psInputs.SetProperty("QuoteId", QuoteId);
                    psInputs.SetProperty("OUIjSId", OUIjSId);
                    
                    console.log("updateSQdetails: Invoking with params - QuoteId:", QuoteId, "OUIjSId:", OUIjSId, "Method:", methodName);
                    
                    // Invoke the business service
                    psOutputs = bsService.InvokeMethod("Run Process", psInputs);
                    
                    // Check for errors
                    if (psOutputs) {
                        const errorMsg = psOutputs.GetProperty("Error Message") || psOutputs.GetProperty("ErrorMessage");
                        
                        if (errorMsg && errorMsg !== "Success" && errorMsg !== "") {
                            console.error("updateSQdetails: Service returned error -", errorMsg);
                            return false;
                        }
                        
                        console.log("updateSQdetails: Success -", psOutputs.GetProperty("Error Message") || "Method executed");
                        
                        // Execute callback if provided
                        if (typeof callback === "function") {
                            callback(psOutputs);
                        }
                        
                        return true;
                    } else {
                        console.error("updateSQdetails: No response from service");
                        return false;
                    }
                    
                } catch (error) {
                    console.error("updateSQdetails: Exception occurred -", error);
                    return false;
                }
            }
            
