			//Marvin: Added for CM-8949
			function fnGetEndDate(term)
			{
				const startDate = new Date();
				const formatStartDate = startDate.toLocaleDateString('en-GB');
				let strYear = startDate.getFullYear();
				let strMonth = startDate.getMonth() + parseInt(term);
				let strDate = startDate.getDate();
				const endDate = new Date(strYear,strMonth,strDate);
				const formatEndDate = endDate.toLocaleDateString('en-GB');
				
				return formatEndDate;
			}
